pub fn load_gemm_heavy_checkpoint(index: usize, out: &mut [i32]) -> usize {
    match index {
        0 => { if out.len() < 192 { return 0; } out[..192].copy_from_slice(&GEMM_HEAVY_STATE_0); 192 },
        1 => { if out.len() < 160 { return 0; } out[..160].copy_from_slice(&GEMM_HEAVY_STATE_1); 160 },
        2 => { if out.len() < 160 { return 0; } out[..160].copy_from_slice(&GEMM_HEAVY_STATE_2); 160 },
        3 => { if out.len() < 128 { return 0; } out[..128].copy_from_slice(&GEMM_HEAVY_STATE_3); 128 },
        4 => { if out.len() < 128 { return 0; } out[..128].copy_from_slice(&GEMM_HEAVY_STATE_4); 128 },
        5 => { if out.len() < 96 { return 0; } out[..96].copy_from_slice(&GEMM_HEAVY_STATE_5); 96 },
        6 => { if out.len() < 96 { return 0; } out[..96].copy_from_slice(&GEMM_HEAVY_STATE_6); 96 },
        7 => { if out.len() < 64 { return 0; } out[..64].copy_from_slice(&GEMM_HEAVY_STATE_7); 64 },
        8 => { if out.len() < 64 { return 0; } out[..64].copy_from_slice(&GEMM_HEAVY_STATE_8); 64 },
        9 => { if out.len() < 48 { return 0; } out[..48].copy_from_slice(&GEMM_HEAVY_STATE_9); 48 },
        10 => { if out.len() < 48 { return 0; } out[..48].copy_from_slice(&GEMM_HEAVY_STATE_10); 48 },
        11 => { if out.len() < 32 { return 0; } out[..32].copy_from_slice(&GEMM_HEAVY_STATE_11); 32 },
        12 => { if out.len() < 10 { return 0; } out[..10].copy_from_slice(&GEMM_HEAVY_STATE_12); 10 },
        _ => 0,
    }
}

pub fn gemm_heavy_checkpoint_matches(index: usize, data: &[i32], len: usize) -> bool {
    match index {
        0 => len == 192 && data == &GEMM_HEAVY_STATE_0[..],
        1 => len == 160 && data == &GEMM_HEAVY_STATE_1[..],
        2 => len == 160 && data == &GEMM_HEAVY_STATE_2[..],
        3 => len == 128 && data == &GEMM_HEAVY_STATE_3[..],
        4 => len == 128 && data == &GEMM_HEAVY_STATE_4[..],
        5 => len == 96 && data == &GEMM_HEAVY_STATE_5[..],
        6 => len == 96 && data == &GEMM_HEAVY_STATE_6[..],
        7 => len == 64 && data == &GEMM_HEAVY_STATE_7[..],
        8 => len == 64 && data == &GEMM_HEAVY_STATE_8[..],
        9 => len == 48 && data == &GEMM_HEAVY_STATE_9[..],
        10 => len == 48 && data == &GEMM_HEAVY_STATE_10[..],
        11 => len == 32 && data == &GEMM_HEAVY_STATE_11[..],
        12 => len == 10 && data == &GEMM_HEAVY_STATE_12[..],
        _ => false,
    }
}
